// ---------------------------------------------------------------------
// Infinite Gallery — STEP 1 placeholder media data
// ---------------------------------------------------------------------
// Split out from main.js because the data below is large (base64 image
// data), not logic — keeping it separate keeps main.js itself readable
// and keeps the "swap this for STEP 2" boundary in one small, obvious
// place. Loaded before main.js; see main.js for how it's consumed.
//
// WHY DATA URIs INSTEAD OF FILE PATHS (important — do not "simplify"
// this back to plain relative paths like assets/infinite-gallery/...):
// this portfolio is opened directly as a local file
// (file:///D:/Projects/Portfolio/Frontend/...), and Chrome refuses to
// upload a file://-loaded <img> into a WebGL texture at all — it can't
// verify the image is same-origin, so it throws
// "SecurityError: The image element contains cross-origin data" and the
// texture never renders. A data: URI has no such restriction, because
// the pixel data is already embedded in the document/script rather than
// fetched separately. The original JPGs this data was generated from
// still live in assets/infinite-gallery/placeholders/ for reference.
//
// STEP 2: a real resource manifest can keep using data: URIs for small
// assets, or move to plain file paths once the Gallery is served from
// an actual web server instead of opened via file:// — that decision
// belongs to STEP 2, not this file.
(function (global) {
  "use strict";

  global.InfiniteGallery = global.InfiniteGallery || {};
  global.InfiniteGallery.PLACEHOLDER_MEDIA = [
    { url: "data:image/jpeg;base64,", width: 1200, height: 900, title: "UI / UX" },
    { url: "data:image/jpeg;base64,", width: 1200, height: 900, title: "Design" },
    { url: "data:image/jpeg;base64,", width: 1200, height: 900, title: "Tech" },
    { url: "data:image/jpeg;base64,", width: 1200, height: 900, title: "Research" },
    { url: "data:image/jpeg;base64,", width: 1200, height: 900, title: "Experiment" },
  ];
})(window);
